fun bubble_sort(values: ref List[i64]) -> () = {
    var end = values.length();
    while (end > 1) {
        var swapped = false;
        var i: i64 = 0;
        while (i + 1 < end) {
            if (values.at(i) > values.at(i + 1)) {
                let temporary: i64 = values.at(i);
                values.at(i) = values.at(i + 1);
                values.at(i + 1) = temporary;
                swapped = true;
            }
            i = i + 1;
        }
        if (not swapped) return;
        end = end - 1;
    }
}

